<?php
require_once 'functions.php';require_login();$me=current_user();$pageTitle='Riwayat Saya';$active='purchases';$st=$pdo->prepare("SELECT p.*, (SELECT COUNT(*) FROM purchases p2 WHERE p2.user_id=p.user_id AND (p2.purchase_date<p.purchase_date OR (p2.purchase_date=p.purchase_date AND p2.id<=p.id))) seq FROM purchases p WHERE p.user_id=? ORDER BY p.purchase_date DESC,p.id DESC");$st->execute([$me['id']]);$rows=$st->fetchAll();require 'header.php';?>
<div class="section-head"><div><p class="eyebrow">LOYALTY HISTORY</p><h3>Riwayat Pembelian Saya</h3></div></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Ukuran</th><th>Status Reward</th><th>Catatan</th></tr></thead><tbody><?php foreach($rows as $r):$free=((int)$r['seq']%5===0); ?><tr><td><?=e($r['purchase_date'])?></td><td><?=e(format_ml($r['ml']))?> ml</td><td><?=$free?'<span class="pill gold-pill">GRATIS</span>':'Pembelian '.(((int)$r['seq']-1)%5+1)?></td><td><?=e($r['notes']?:'—')?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4" class="empty">Belum ada riwayat pembelian.</td></tr><?php endif; ?></tbody></table></div><?php require 'footer.php'; ?>
